CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS stories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,subtitle TEXT,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL CHECK(category IN ('children','teen','adult','romance','true-crime','original')),age_rating TEXT NOT NULL DEFAULT 'all-ages',reading_level TEXT NOT NULL DEFAULT 'A1',estimated_minutes INT NOT NULL DEFAULT 5,cover_theme TEXT NOT NULL DEFAULT 'meadow',source_version INT NOT NULL DEFAULT 1,is_published BOOLEAN NOT NULL DEFAULT FALSE,is_featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS story_chapters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,chapter_number INT NOT NULL,title TEXT NOT NULL,master_content JSONB NOT NULL DEFAULT '[]',UNIQUE(story_id,chapter_number));
CREATE TABLE IF NOT EXISTS story_translations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,language_code TEXT NOT NULL,reading_level TEXT NOT NULL,source_version INT NOT NULL,translation_version INT NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','failed')),provider TEXT,translated_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(story_id,language_code,reading_level,source_version));
CREATE TABLE IF NOT EXISTS translated_chapters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),translation_id UUID NOT NULL REFERENCES story_translations(id) ON DELETE CASCADE,chapter_number INT NOT NULL,content JSONB NOT NULL DEFAULT '[]',UNIQUE(translation_id,chapter_number));
CREATE TABLE IF NOT EXISTS vocabulary (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,language_code TEXT NOT NULL,lemma TEXT NOT NULL,display_form TEXT NOT NULL,translation TEXT NOT NULL,part_of_speech TEXT,grammatical_gender TEXT,pronunciation TEXT,difficulty TEXT,context_note TEXT,UNIQUE(story_id,language_code,lemma));
CREATE TABLE IF NOT EXISTS user_profiles (id TEXT PRIMARY KEY,display_name TEXT,native_language TEXT NOT NULL DEFAULT 'en',learning_language TEXT NOT NULL DEFAULT 'fr',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reading_progress (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,chapter_number INT NOT NULL DEFAULT 1,sentence_index INT NOT NULL DEFAULT 0,completed BOOLEAN NOT NULL DEFAULT FALSE,last_read_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,story_id));
CREATE TABLE IF NOT EXISTS word_progress (user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,vocabulary_id UUID NOT NULL REFERENCES vocabulary(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','learning','known')),correct_recalls INT NOT NULL DEFAULT 0,last_reviewed_at TIMESTAMPTZ,next_review_at TIMESTAMPTZ,PRIMARY KEY(user_id,vocabulary_id));
CREATE TABLE IF NOT EXISTS user_streaks (user_id TEXT PRIMARY KEY REFERENCES user_profiles(id) ON DELETE CASCADE,current_streak INT NOT NULL DEFAULT 0,longest_streak INT NOT NULL DEFAULT 0,last_activity_date DATE,streak_savers INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,icon TEXT NOT NULL DEFAULT 'sparkles',xp_reward INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS user_achievements (user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,achievement_id TEXT NOT NULL REFERENCES achievements(id) ON DELETE CASCADE,unlocked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,achievement_id));
CREATE INDEX IF NOT EXISTS idx_stories_category ON stories(category,is_published);
CREATE INDEX IF NOT EXISTS idx_translations_lookup ON story_translations(story_id,language_code,reading_level,status);
CREATE INDEX IF NOT EXISTS idx_vocabulary_story_language ON vocabulary(story_id,language_code);
CREATE INDEX IF NOT EXISTS idx_reading_progress_user ON reading_progress(user_id,last_read_at DESC);
CREATE INDEX IF NOT EXISTS idx_word_review_due ON word_progress(user_id,next_review_at);\n-- Personal EPUB library and reusable sentence-level translation cache.\nCREATE TABLE IF NOT EXISTS imported_books (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,title TEXT NOT NULL,author TEXT,original_language TEXT,file_name TEXT,file_size_bytes BIGINT,import_status TEXT NOT NULL DEFAULT 'ready' CHECK(import_status IN ('processing','ready','failed')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());\nCREATE TABLE IF NOT EXISTS imported_book_chapters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),book_id UUID NOT NULL REFERENCES imported_books(id) ON DELETE CASCADE,chapter_number INT NOT NULL,title TEXT NOT NULL,content JSONB NOT NULL DEFAULT '[]',UNIQUE(book_id,chapter_number));\nCREATE TABLE IF NOT EXISTS sentence_translations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id TEXT REFERENCES user_profiles(id) ON DELETE CASCADE,content_hash TEXT NOT NULL,source_language TEXT NOT NULL,target_language TEXT NOT NULL,reading_level TEXT NOT NULL DEFAULT 'natural',source_text TEXT NOT NULL,translated_text TEXT NOT NULL,provider TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,content_hash,target_language,reading_level));\nCREATE INDEX IF NOT EXISTS idx_imported_books_user ON imported_books(user_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_imported_chapters_book ON imported_book_chapters(book_id,chapter_number);\nCREATE INDEX IF NOT EXISTS idx_sentence_translation_lookup ON sentence_translations(content_hash,target_language,reading_level);\n